"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[601],{7601:(e,t,a)=>{a.d(t,{IO:()=>s,Lg:()=>i,ME:()=>n,oJ:()=>o});let n={name:"Venkata Tarun Kumar Mavillapalli",shortName:"Venkata Tarun",role:"AI Engineer & Data Professional",email:"mvtkop760@gmail.com",github:"https://github.com/VenkataTarunKumarMavillapalli",linkedin:"https://www.linkedin.com/in/venkata-tarun-kumar-mavillapalli-967b4613a/"},i=[{label:"Home",href:"/"},{label:"About",href:"/about/"},{label:"Work",href:"/work/"},{label:"Timeline",href:"/timeline/"},{label:"Learning",href:"/learning/"},{label:"Contact",href:"/contact/"}],o=[{slug:"world-food-programme",title:"AI, reporting and automation at WFP",organisation:"World Food Programme \xb7 United Nations",role:"AI Engineer Intern — Integration & Investigative Technologies",kind:"Experience",period:"Oct 2025 – Jun 2026",start:202510,end:202606,location:"Rome, Italy",summary:"I built AI tools, dashboards and automated workflows for the Office of Inspections and Investigations.",overview:["My work at the World Food Programme brought together AI engineering, data preparation, reporting and automation. I worked within the Office of Inspections and Investigations, where handling sensitive information carefully was part of the job.","The tools needed to help people find information, prepare documents and follow operational work. I worked on systems that kept links to source material and included human review. Because the work is confidential, I describe the capabilities here without sharing case information."],sections:[{title:"Finding information with AI",text:"I developed retrieval-augmented generation systems, often called RAG. These systems find relevant information in a collection before an AI model uses it to answer a question. I combined keyword, semantic and vector search with re-ranking and agent orchestration using Azure AI Search, Azure AI Foundry and GPT models."},{title:"Preparing the underlying data",text:"I built pipelines to ingest, validate, index and create embeddings for more than 9,000 oversight records. I also supported the preparation of more than one million forensic records and messages through parsing, normalisation, validation, secure storage and indexing. Keeping source links and metadata was important for tracing an answer back to the records behind it."},{title:"Helping with documents",text:"I built AI-assisted drafting and review workflows that accepted different document formats. They included citations, quality checks, structured exports and a human review step. The aim was to support the person reviewing the material while keeping the supporting information visible."},{title:"Making reporting easier",text:"I created 39 Power BI dashboards for executive, chief-level and operational users. They covered workload, key performance indicators, case ageing, intake and regional trends. I also automated SharePoint-connected reporting pipelines, reaching approximately 95% daily refresh automation and reducing manual reporting work."},{title:"Connecting requests and approvals",text:"Using Logic Apps, Power Automate and SharePoint Lists, I developed workflows for requests, approvals, notifications, status tracking and escalation. I also wrote technical documentation, governance materials, deployment notes and handover resources, and worked with international teams on planning, demos, feedback and testing."}],tools:["Azure AI Foundry","Azure AI Search","Azure OpenAI","Python","Power BI","Power Automate","Logic Apps","SharePoint"],closing:"This role combined building the tools with preparing the data, documenting decisions and helping colleagues use and maintain the systems.",source:["resume:1"]},{slug:"efsa",title:"Data quality and internal tools at EFSA",organisation:"European Food Safety Authority",role:"Data Officer Trainee — Data Management and Analysis Team",kind:"Experience",period:"Nov 2024 – Oct 2025",start:202411,end:202510,location:"Parma, Italy",summary:"I worked on data quality dashboards, CRM checks, Databricks applications and documentation for data products.",overview:["At EFSA, I worked in the Integrated Data Unit on data management and product support. Much of my work focused on checking that information was consistent across systems and making those checks easier for other teams to use.","I worked with analysts, engineers, product managers, domain specialists and scientists. Alongside implementation, I wrote documentation so that people could understand how the products worked and continue using them."],sections:[{title:"Checking data quality",text:"I designed four Power BI dashboards with more than 30 automated business rules and Terraform-based Databricks pipelines. The work covered more than 100,000 CRM records, six dimensions of data quality and three business units: FDP, ENREL and KNOW. The dashboards made discrepancies visible and supported ongoing monitoring."},{title:"Reducing repetitive ticket updates",text:"I built the Azure DevOps Closed Date Updater, a secure Databricks application connected to the Azure DevOps API. It automated updates for more than 25 Agile tickets each month, kept a complete audit trail and saved more than five hours of monthly manual work."},{title:"Comparing information across systems",text:"I created a Salesforce–Databricks comparison pipeline that automated the export and validation of more than 59,000 CRM records. I also refactored five Python notebooks into modular Databricks components, improving the reliability and maintainability of the Nos extractor."},{title:"Making the work maintainable",text:"I used Databricks branches and Azure DevOps commits to prepare changes for controlled deployment. I wrote user and developer documentation for three EFSA data products, covering architecture, setup, data logic and troubleshooting, and supported ad hoc CRM analyses."},{title:"Building with other trainees",text:"I was a founding member of the trainee-powered scrum team under HUCAP. We worked on an internal platform for sharing ad hoc learning and collaboration opportunities across EFSA units. This brought product design and cross-team collaboration into my data-focused role."}],tools:["Power BI","Databricks","Python","Terraform","Azure DevOps","Salesforce"],closing:"The work made data checks more repeatable, reduced routine updates and gave colleagues clearer information about how the data products operated.",source:["resume:1"]},{slug:"cryptocurrency-discourse",title:"Research into cryptocurrency white papers",organisation:"University of Naples Federico II",role:"Data Science Research Intern",kind:"Experience",period:"May 2024 – Oct 2024",start:202405,end:202410,location:"Naples, Italy",summary:"I used language analysis and network methods to study topics, entities and relationships across 21 white papers.",overview:["During this research internship, I studied cryptocurrency white papers using natural language processing and network analysis. The work looked at how ideas, entities and relationships appeared across a collection of 21 documents.","The research combined data science with computational social science. I helped refine research questions, interpret results and place the findings in a wider social and technical context."],sections:[{title:"Reading patterns across documents",text:"I used named entity recognition to identify entities, topic modelling with Latent Dirichlet Allocation to explore themes, and dependency parsing to examine language structure. Sentiment analysis and semantic network analysis provided other ways to look at the same material."},{title:"Exploring connections",text:"I used entity co-occurrence analysis to examine which entities appeared together. I also applied social network analysis, text classification and clustering to study groups and communication structures in the documents."},{title:"Interpreting the findings",text:"I worked with the research team to extract and bring together topics, entities and relationships. The analysis was part of an iterative research process: refining the questions, examining the results and considering what those results could reasonably tell us."}],tools:["Natural language processing","Named entity recognition","Topic modelling","Network analysis","Text classification","Clustering"],closing:"I received a Certificate of Research Excellence and a recommendation for PhD programmes following this work.",source:["resume:1"]},{slug:"eeg-model-uncertainty",title:"Infotainment training and model evaluation",organisation:"Italdesign Giugiaro \xb7 Ideneers Academy",role:"Infotainment Intern",kind:"Experience",period:"May 2024 – Aug 2024",start:202405,end:202408,location:"",summary:"I completed practical training in in-vehicle infotainment and worked on uncertainty in EEG classification models.",overview:["At the Ideneers Academy, I completed more than 400 hours of theoretical and practical training in in-vehicle infotainment systems. I ranked first in the programme.","My curricular internship also included thesis work under Professor Leopoldo Angrisani: “A Metrological Approach to Uncertainty Evaluation in Model Performance: A Case Study on EEG Signals Classification.”"],sections:[{title:"Training in infotainment systems",text:"The programme covered in-vehicle infotainment through both theory and practice. This gave me experience with a different application of technology alongside my data science studies."},{title:"Looking at uncertainty in model performance",text:"The thesis considered how uncertainty can be evaluated when assessing a classification model. EEG signal classification was the case study. The focus was on understanding model performance through a metrological approach, rather than treating a performance score as a complete picture."}],tools:["In-vehicle infotainment","Model evaluation","Uncertainty evaluation","EEG classification"],closing:"This experience connected practical technical training with my research into how machine learning models are evaluated.",source:["resume:2"]},{slug:"salesforce-and-chatbots",title:"Salesforce development and customer-service tools",organisation:"NeuraFlash",role:"Associate Salesforce Developer",kind:"Experience",period:"Feb 2021 – Aug 2022",start:202102,end:202208,location:"Hyderabad, India",summary:"I configured Salesforce, developed Amazon Connect chatbots and supported systems in production.",overview:["At NeuraFlash, I worked on Salesforce configurations and customer-service tools. The role included implementing changes, collaborating with other teams and resolving issues after systems were in use."],sections:[{title:"Configuring Salesforce",text:"I designed and implemented page layouts, sharing settings and dashboards. These changes shaped how users accessed information and worked within Salesforce."},{title:"Working on automated customer service",text:"I developed and configured Amazon Connect chatbots to support automated customer-service interactions. This work sat alongside the Salesforce development and configuration tasks in my role."},{title:"Supporting live systems",text:"I investigated and resolved production issues. I used Lucid Charts for process diagrams, GitHub for version control, Jira for project tracking, OpsGenie for incident management and Confluence for documentation and knowledge sharing."}],tools:["Salesforce","Amazon Connect","GitHub","Jira","OpsGenie","Confluence","Lucid Charts"],closing:"The role gave me experience across development, team coordination and the ongoing support that software needs after release.",source:["resume:2"]},{slug:"drexel-web-development",title:"Website and database development",organisation:"A.J. Drexel Autism Institute",role:"Website & Database Development Intern",kind:"Experience",period:"May 2019 – Jul 2019",start:201905,end:201907,location:"Philadelphia, USA",summary:"I redesigned a website for mobile use and led a team working on the website and its database.",overview:["During my internship at the A.J. Drexel Autism Institute, I worked on redesigning and developing a mobile-first website. The work included changes to the user interface as well as database development."],sections:[{title:"Improving the website",text:"I redesigned the site around mobile use and improved its user-interface components. The redesigned website achieved twice the performance speed of the earlier version."},{title:"Coordinating the work",text:"I led a cross-functional team using Scrum. I oversaw database creation and delegated tasks, combining hands-on development with responsibility for organising the team’s work."}],tools:["Web development","Database development","Mobile-first design","Scrum"],closing:"This internship brought together website development, database work and practical experience leading a team.",source:["resume:2"]},{slug:"data-analyst-agent",title:"Data Analyst Agent",organisation:"Azure AI Foundry + Semantic Kernel",role:"Independent implementation based on a solution accelerator",kind:"Project",period:"Date not specified",start:null,end:null,location:"",summary:"I adapted an agent-based solution accelerator into an assistant with access to data tools and search.",overview:["I replicated and customised an agent-based solution accelerator using Azure AI Foundry and Semantic Kernel. The work involved building an AI assistant and connecting it to the tools and services needed to handle analytical questions.","This was an adaptation of an existing accelerator. My work focused on customising the implementation and integrating the supporting services."],sections:[{title:"Connecting models and data tools",text:"I used the Semantic Kernel Agent Framework with Azure AI Foundry, OpenAI and Llama models, and Azure Databricks plugins. Code Interpreter and Bing Search through Foundry Agent Tools supported grounding and reasoning during a session."},{title:"Managing user sessions",text:"I worked with a Session Manager and WebSocket connections, and integrated Microsoft Entra ID for identity and Azure AI Content Safety for content checks."},{title:"Supporting the application",text:"Azure Key Vault, API Management, Application Insights and Cosmos DB supported secrets management, service access, monitoring and application state. These services formed the infrastructure around the assistant."}],tools:["Semantic Kernel","Azure AI Foundry","Databricks","Cosmos DB","Microsoft Entra ID","Key Vault","API Management","Application Insights"],closing:"The result was a customised agent-based assistant with data connections, session handling and supporting Azure infrastructure.",source:["resume:2"]},{slug:"financial-reports-copilot",title:"Copilot for Financial Reports",organisation:"Microsoft Azure AI services",role:"Independent implementation based on Microsoft’s Advanced RAG accelerator",kind:"Project",period:"Date not specified",start:null,end:null,location:"",summary:"I adapted a retrieval-based AI assistant for finding and using information in financial reports.",overview:["I replicated and customised Microsoft’s Advanced RAG solution accelerator. RAG means retrieval-augmented generation: the application finds relevant information from documents and gives that information to a model to help it answer a question.","The implementation used Azure OpenAI and Azure Cognitive Search, with supporting services for document ingestion, sessions, authentication and monitoring."],sections:[{title:"Retrieving information from documents",text:"I worked with GPT-4, Azure Cognitive Search and custom skills orchestration to build the knowledge retrieval assistant. The system combined document search with an AI-generated response."},{title:"Organising the application services",text:"I implemented microservices for session management, query orchestration and document ingestion using AKS, Redis Cache and Azure Functions. Cosmos DB and Azure Storage supported persistent state and storage, while Key Vault handled secrets."},{title:"Configuring and monitoring the system",text:"I integrated Microsoft Entra ID, API Management, Azure Monitor, Application Insights and Log Analytics. I also used a Configuration Service for runtime settings and automated evaluation through nightly test runs and logging flows."}],tools:["Azure OpenAI","Azure Cognitive Search","AKS","Azure Functions","Redis","Cosmos DB","Key Vault","Azure Monitor"],closing:"The project brought together document retrieval, application services and operational tooling in a customised version of the Microsoft accelerator.",source:["resume:2"]},{slug:"course-recommender",title:"A course recommendation system",organisation:"Machine Learning Capstone",role:"Capstone project",kind:"Project",period:"Date not specified",start:null,end:null,location:"",summary:"I explored different ways to recommend online courses from course content and enrolment data.",overview:["This project looked at how a recommendation system could help learners find courses that interest them. I worked with online-course enrolment data and course descriptions, and compared content-based and collaborative-filtering approaches."],sections:[{title:"Understanding the data",text:"I collected and explored the course enrolment data. I also represented course text using Bag of Words, which describes text through word occurrences, and used those representations to calculate similarities between courses."},{title:"Recommending from course content",text:"I built content-based recommendation approaches using similarity measures, K-means clustering and principal component analysis. These approaches use the characteristics of courses to find related options."},{title:"Learning from enrolment patterns",text:"I explored collaborative-filtering approaches using nearest neighbours, non-negative matrix factorisation, neural networks and regression and classification methods. I brought the work together in a presentation explaining the analysis and approaches."}],tools:["Exploratory data analysis","Bag of Words","K-means","PCA","Nearest neighbours","Matrix factorisation","Neural networks"],closing:"The project compared several ways of making recommendations and presented the work as a capstone study.",source:["resume:2"]},{slug:"news-classification",title:"Analysing and classifying news",organisation:"Natural language processing project",role:"Machine learning project",kind:"Project",period:"Date not specified",start:null,end:null,location:"",summary:"I compared text-analysis methods and classification models, then brought them into an interactive Streamlit application.",overview:["This project explored the classification of fake and real news using natural language processing. I worked on the analysis of the text, the way it was represented for models, and the interface used to explore predictions.","The work compared traditional machine learning and deep learning models. It also explored how the choice of text representation affected classification."],sections:[{title:"Exploring the text",text:"I examined readability, word co-occurrence, sentiment, named entities, topics and association rules. This helped describe the dataset before training models."},{title:"Comparing representations and models",text:"I used TF-IDF and Word2Vec representations, and evaluated logistic regression, random forests, multilayer perceptrons, recurrent networks, transformers and a fine-tuned BERT model. I built preprocessing steps for tokenisation, vectorisation and padding so the models could handle texts of different lengths."},{title:"Building an interface for the results",text:"I created an interactive Streamlit application that brought together multiple models and text-analysis features. It displayed predictions with confidence scores and sentiment categories, making the model outputs easier to inspect."}],tools:["TF-IDF","Word2Vec","BERT","Neural networks","Text preprocessing","Streamlit"],closing:"The project combined an analysis workflow, model comparisons and an interactive way to explore classification results.",source:["resume:2"]},{slug:"colony-weight-forecasting",title:"Forecasting insect colony weight",organisation:"Time series analysis project",role:"Data science project",kind:"Project",period:"Date not specified",start:null,end:null,location:"",summary:"I used historical colony and environmental data to forecast weight and explore the results in Power BI.",overview:["The aim of this project was to predict an insect colony’s weight over time. I worked with colony and environmental data, explored patterns in the historical records and created additional features for the models."],sections:[{title:"Preparing and exploring the data",text:"I carried out exploratory data analysis and feature engineering. This helped organise the historical measurements and environmental information for the forecasting work."},{title:"Comparing forecasts",text:"I developed models using ARIMA, SARIMA, linear regression, decision trees and other machine learning methods. I evaluated errors using MSE, RMSE and MAPE: different measures of the gap between predicted and observed values."},{title:"Making the data easier to explore",text:"I built an interactive Power BI dashboard to visualise historical data and support time series analysis alongside the predictive model."}],tools:["Time series analysis","ARIMA","SARIMA","Regression","Decision trees","Power BI"],closing:"The deliverables were a predictive model and an interactive dashboard for exploring the time series.",source:["resume:2"]},{slug:"google-fiber-bi",title:"Understanding repeat customer calls",organisation:"Google Fiber \xb7 Business Intelligence Capstone",role:"Capstone project",kind:"Project",period:"Date not specified",start:null,end:null,location:"",summary:"I built a dashboard and supporting documents to examine repeat customer-service calls in the Google Fiber capstone scenario.",overview:["This capstone used a Google Fiber customer-service scenario to explore repeat calls. It was a learning project, rather than employment at Google Fiber.","The work connected a business question with requirements, data processing and dashboard design: which issues were leading to repeated calls, and how did those patterns vary across markets and time?"],sections:[{title:"Defining what the dashboard needed to answer",text:"I prepared a Stakeholder Requirements Document, a Project Requirements Document and a Planning Document. These set out the questions, requirements and planned work."},{title:"Working with the data",text:"I used BigQuery, SQL, Tableau and Google Sheets for data processing and visualisation. The analysis examined call frequency, issue types and trends across markets and time periods."},{title:"Presenting the patterns",text:"I designed dashboards that made repeat-call patterns easier to compare. The analysis also considered how those patterns could inform customer-satisfaction improvements within the scenario."}],tools:["BigQuery","SQL","Tableau","Google Sheets","Requirements documentation"],closing:"The project produced structured planning documents and dashboards that explained repeat-call patterns.",source:["resume:2"]}],s=[...o.filter(e=>"Experience"===e.kind).map(e=>({id:e.slug,title:e.role,organisation:e.organisation,period:e.period,start:e.start,category:"Work",summary:e.summary,details:e.overview,href:`/work/${e.slug}/`,linkLabel:"Read about this role"})),...[{id:"masters",title:"MSc in Data Science",organisation:"University of Naples Federico II",period:"Sep 2022 – May 2025",start:202209,end:202505,location:"Naples, Italy",summary:"My master’s programme focused on data science in public administration, economics and management.",paragraphs:["I studied the technical and social sides of working with data: how it is stored and analysed, how models are built, and how evidence is used in organisations. My reported result was 88%.","During the programme, I also built more than 20 AI agents and RAG systems as side projects. This gave me hands-on experience with language models, developer tools and AI frameworks alongside the formal coursework."],subjects:["Data mining and text mining","Statistical data analysis","Big data architecture and data management","Information systems and business intelligence","Theory and ethics of big data","Social science methods and economic analysis"],source:["resume:3"]},{id:"apple-academy",title:"Digital Product Development & Management",organisation:"Apple Developer Academy",period:"Sep 2023 – Jun 2024",start:202309,end:202406,location:"Europe",summary:"A nine-month programme combining iOS development, design and product thinking.",paragraphs:["I worked in international teams on iOS app development, user-centred design, branding, accessibility and prototyping. We used Challenge-based Learning to develop ideas and organise work across disciplines.","My contributions also included idea validation, business models and value propositions. The programme connected coding and interface development with the decisions involved in taking a product from concept to release."],subjects:["iOS app and interface development","User-centred design and accessibility","Prototyping and branding","Idea validation and business models","Challenge-based Learning and collaboration"],source:["resume:3"]},{id:"bachelors",title:"BTech in Computer Science Engineering",organisation:"Amity University \xb7 Birkbeck University \xb7 Adelphi University",period:"Aug 2016 – Jul 2020",start:201608,end:202007,location:"India \xb7 United Kingdom \xb7 United States",summary:"A three-continental computer science programme across India, the UK and the US.",paragraphs:["My undergraduate studies took place at Amity University in India, Birkbeck University in London and Adelphi University in New York. The programme provided a foundation in computer science, software development and the systems that applications depend on.","Alongside my studies, I took part in student organisations, sport and university events. I also completed a website and database development internship at the A.J. Drexel Autism Institute in Philadelphia."],subjects:["Data structures, algorithms and databases","Operating systems and computer architecture","Computer networks and distributed systems","Software engineering and mobile computing","Python, machine learning and artificial intelligence","Cloud computing, mathematics and statistics"],source:["resume:3"]}].map(e=>({id:e.id,title:e.title,organisation:e.organisation,period:e.period,start:e.start,category:"Education",summary:e.summary,details:e.paragraphs,href:`/learning/#${e.id}`,linkLabel:"Read about this programme"})),...[{id:"azure-ai-engineer",title:"Microsoft Certified: Azure AI Engineering Associate",issuer:"Microsoft",date:"Jun 2025",start:202506,source:["resume:3"]},{id:"azure-ai-fundamentals",title:"Microsoft Certified: Azure AI Fundamentals",issuer:"Microsoft",date:"Jun 2025",start:202506,source:["resume:3"]},{id:"mckinsey-forward",title:"McKinsey Forward Program",issuer:"McKinsey & Company",date:"Jul 2024",start:202407,source:["resume:3"]},{id:"ibm-machine-learning",title:"IBM Machine Learning Professional Certificate",issuer:"IBM",date:"Sep 2023",start:202309,source:["resume:3"]},{id:"google-bi",title:"Google Business Intelligence",issuer:"Coursera",date:"Apr 2023",start:202304,source:["resume:3"]},{id:"risk-management",title:"Risk Management Systems — ISO 31000:2018",issuer:"BSI",date:"Jan 2020",start:202001,source:["resume:3"]},{id:"quality-management",title:"Quality Management Systems — ISO 9001:2015",issuer:"BSI",date:"Dec 2018",start:201812,source:["resume:3"]}].map(e=>({id:e.id,title:e.title,organisation:e.issuer,period:e.date,start:e.start,category:"Certifications",summary:`${e.issuer} \xb7 ${e.date}`,details:[`I completed ${e.title} in ${e.date}.`],href:"/learning/#certifications",linkLabel:"View certifications and programmes"})),{id:"singapore-conference",title:"Technology in business intelligence",organisation:"National University of Singapore \xb7 Shaw Foundation",period:"2017",start:201700,category:"Conference",summary:"I attended the International Conference on the Role of Technology in Business Intelligence.",details:["I took part in this conference in Singapore during my undergraduate programme. It is one of the academic activities listed alongside my computer science studies."],href:"/learning/#research",linkLabel:"View research and conferences"}]}}]);